import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

public class MonitoringAgent {

    private static final Map<String, Boolean> featureFlags = new ConcurrentHashMap<>();
    private static final String LOG_ENDPOINT = "http://logging-service:8080/ingest";
    private static volatile PrintWriter logWriter;

    static {
        featureFlags.put("structured_logging", true);
        featureFlags.put("enriched_headers", true);
        featureFlags.put("legacy_format", false);
        featureFlags.put("unicode_normalization", true);
    }

    public static void initialize(String logPath) throws IOException {
        logWriter = new PrintWriter(new BufferedWriter(new FileWriter(logPath, true)), true);
    }

    public static void updateFeatureFlag(String flag, boolean value) {
        if (featureFlags.containsKey(flag)) {
            featureFlags.put(flag, value);
        }
    }

    /**
     * Encodes a field value for safe inclusion in structured log entries.
     * Handles control characters based on feature flag configuration.
     */
    private static String encodeFieldValue(String value) {
        if (value == null) return "";

        StringBuilder encoded = new StringBuilder(value.length());
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (c == '\\') {
                encoded.append("\\\\");
            } else if (c == '"') {
                encoded.append("\\\"");
            } else if (c < 0x20) {
                // Control character handling
                encoded.append(String.format("\\u%04x", (int) c));
            } else {
                encoded.append(c);
            }
        }
        return encoded.toString();
    }

    /**
     * Normalizes Unicode sequences in the input string.
     * When unicode_normalization flag is enabled, resolves escape sequences
     * to their character equivalents for consistent storage.
     * Only resolves printable characters (0x20 and above) to prevent injection.
     */
    private static String normalizeUnicode(String input) {
        if (!featureFlags.getOrDefault("unicode_normalization", false)) {
            return input;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        while (i < input.length()) {
            if (i + 5 < input.length() && input.charAt(i) == '\\' && input.charAt(i + 1) == 'u') {
                String hex = input.substring(i + 2, i + 6);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    if (codePoint >= 0x20) {
                        result.append((char) codePoint);
                    } else {
                        result.append(String.format("\\u%04x", codePoint));
                    }
                    i += 6;
                } catch (NumberFormatException e) {
                    result.append(input.charAt(i));
                    i++;
                }
            } else {
                result.append(input.charAt(i));
                i++;
            }
        }
        return result.toString();
    }

    /**
     * Formats a log entry according to the current feature flag configuration.
     * Structured logging produces key=value pairs; legacy produces plain text.
     */
    private static String formatLogEntry(String level, String component, String message, 
                                          Map<String, String> metadata) {
        StringBuilder entry = new StringBuilder();
        long timestamp = System.currentTimeMillis();

        if (featureFlags.getOrDefault("structured_logging", false)) {
            entry.append(String.format("ts=%d level=%s component=%s", timestamp, level, component));

            String encodedMessage = encodeFieldValue(message);
            entry.append(" msg=\"").append(encodedMessage).append("\"");

            if (metadata != null) {
                for (Map.Entry<String, String> meta : metadata.entrySet()) {
                    String key = meta.getKey().replaceAll("[^a-zA-Z0-9_]", "_");
                    String val = encodeFieldValue(meta.getValue());
                    entry.append(" ").append(key).append("=\"").append(val).append("\"");
                }
            }
        } else {
            entry.append(String.format("[%d] [%s] [%s] %s", timestamp, level, component, message));
        }

        return entry.toString();
    }

    /**
     * Sanitizes a value for safe use as an HTTP header value.
     * Rejects any characters outside a conservative allow-list to prevent
     * HTTP header injection (CWE-93) via user-controlled trace identifiers.
     */
    private static String sanitizeHeaderValue(String value) {
        if (value == null) return "";
        StringBuilder sb = new StringBuilder(value.length());
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            // Allow only visible ASCII (excluding control chars, CR, LF, and DEL)
            if (c >= 0x21 && c <= 0x7E) {
                sb.append(c);
            }
            // Any control char (CR/LF included) or non-printable is dropped
        }
        return sb.toString();
    }

    /**
     * Ships a log entry to the remote logging service with enriched headers.
     */
    private static void shipToRemote(String formattedEntry, String traceId) {
        if (!featureFlags.getOrDefault("enriched_headers", false)) {
            return;
        }

        try {
            URL url = new URL(LOG_ENDPOINT);
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("POST");
            conn.setRequestProperty("Content-Type", "application/x-ndjson");
            conn.setRequestProperty("X-Trace-Id", sanitizeHeaderValue(traceId));
            conn.setDoOutput(true);

            try (OutputStream os = conn.getOutputStream()) {
                os.write(formattedEntry.getBytes(StandardCharsets.UTF_8));
            }
            conn.getResponseCode();
            conn.disconnect();
        } catch (IOException e) {
            // Silently fail for remote shipping
        }
    }

    /**
     * Primary logging method. Processes the message through the encoding pipeline
     * and writes to both local file and remote service.
     */
    public static void log(String level, String component, String message, 
                           Map<String, String> metadata, String traceId) {
        if (logWriter == null) return;

        // Step 1: Format the structured log entry (encodes control chars)
        String formatted = formatLogEntry(level, component, message, metadata);

        // Step 2: Apply unicode normalization for consistent storage
        String normalized = normalizeUnicode(formatted);

        // Step 3: Write to local log file
        logWriter.println(normalized);

        // Step 4: Ship to remote if enabled
        if (traceId != null) {
            shipToRemote(normalized, traceId);
        }
    }

    /**
     * Convenience method for application-level logging with user context.
     */
    public static void logUserAction(String userId, String action, String details) {
        Map<String, String> meta = new HashMap<>();
        meta.put("user_id", userId);
        meta.put("action", action);
        log("INFO", "user-activity", details, meta, userId);
    }

    public static void main(String[] args) throws Exception {
        initialize("/var/log/app/monitoring.log");

        // Simulate normal usage
        logUserAction("user-12345", "login", "User logged in from 192.168.1.1");

        // Simulate with potentially malicious input
        String userInput = "Normal action\\u000d\\u000aINFO injected_line=true";
        logUserAction("user-99999", "search", userInput);
    }
}
